using HD2RuntimeGUI.Core.Localization;
using HD2RuntimeGUI.Core.Metadata;
using HD2RuntimeGUI.Core.Services;
using Xunit;

namespace HD2RuntimeGUI.Tests;

// Projects saved by ModBuilder 1.3.1 itself (Fixtures/projects-1.3.1, generated by the v1.3.1 source against SDK 0.27.0: weapons, a
// projectile swap, a support weapon, stratagems, a vehicle and backpack, the SG-20 Halt case, a booster and a throwable). 1.4.0 must open
// each one unchanged on its own SDK, in either UI language, and generate exactly 1.3.1's operations, now each inside the pcall wrapper
// (*.v140.lua is *.v131.lua with only that wrapper applied; for the SG-20 Halt also the branch-qualified field constants that fix
// ModBuilder#2 on HD2Runtime 0.27.0). Rebinding to the pinned SDK is an explicit user action and keeps the edits.
public sealed class OldProjectCompatibilityTests
{
    private static string Folder => Path.Combine(AppContext.BaseDirectory, "Fixtures", "projects-1.3.1");
    public static IEnumerable<object[]> Projects() => Directory.GetFiles(Folder, "*.hd2mod.json").Select(f => new object[] { Path.GetFileName(f)[..^".hd2mod.json".Length] });

    private static async Task<BuilderWorkspace> Open(TestEnvironment e, string name)
    {
        // The user's data folder after upgrading: SDK 0.27.0 installed and current, then 1.4.0 starts with its newer bundled SDK.
        await SdkFixtures.Install(e, "0.27.0");
        var upgraded = new SdkCache(e.Paths, e.Reader, e.GitHub); e.GitHub.Offline = true;
        var w = new BuilderWorkspace(e.Store, e.Projects, upgraded, new SdkUpdateService(upgraded, e.GitHub, e.Paths), e.Changes, e.Generator, e.Exporter, e.Desktop, e.Desktop, e.Paths);
        await w.InitializeAsync();
        Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version);
        var project = await e.Store.ImportAsync(Path.Combine(Folder, name + ".hd2mod.json"));
        await w.OpenAsync(project.Id);
        return w;
    }

    [Theory] [MemberData(nameof(Projects))]
    public async Task A_1_3_1_project_opens_unchanged_and_generates_its_operations_in_either_language(string name)
    {
        var expected = File.ReadAllText(Path.Combine(Folder, name + ".v140.lua")).Replace("\r\n", "\n");
        foreach (var language in UiLanguages.Supported)
            using (UiCulture.Use(language))
            {
                using var e = new TestEnvironment(); var w = await Open(e, name);
                Assert.Equal("0.27.0", w.Project!.SdkVersion); Assert.Null(w.BuildError);
                Assert.Equal(expected, w.LuaPreview);
                if (name == "P6-sg20-halt")
                {
                    // 1.3.1 wrote the generic constants that published 0.27.0 could not resolve on the Halt feeds; everything else is identical.
                    var v131 = File.ReadAllText(Path.Combine(Folder, name + ".v131.lua"));
                    Assert.Contains("hd2.fields.projectile.velocity,", v131); Assert.Contains("hd2.fields.projectile.alternate_velocity,", w.LuaPreview);
                    Assert.Contains("hd2.fields.damage.player_standard_damage,", v131); Assert.Contains("hd2.fields.damage.primary_standard_damage,", w.LuaPreview);
                }
                // Opening never rewrites the saved project (its format and edits stay as 1.3.1 wrote them).
                Assert.True(w.Project.FormatVersion <= 9);
            }
    }

    [Theory] [MemberData(nameof(Projects))]
    public async Task Rebinding_a_1_3_1_project_to_the_pinned_sdk_keeps_its_edits(string name)
    {
        using var e = new TestEnvironment(); var w = await Open(e, name);
        var before = w.Project!.WeaponChanges.Count + w.Project.SupportChanges.Count + w.Project.StratagemChanges.Count + w.Project.EntityChanges.Count + w.Project.ProjectileChanges.Count;
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion);
        Assert.Equal(before, w.Project.WeaponChanges.Count + w.Project.SupportChanges.Count + w.Project.StratagemChanges.Count + w.Project.EntityChanges.Count + w.Project.ProjectileChanges.Count);
        // A rebind either builds directly or names what needs review; it never silently drops an edit.
        Assert.True(w.BuildError == null || w.BuildError.Length > 0);
        if (name == "P6-sg20-halt") { Assert.Null(w.BuildError); Assert.Contains("hd2.weapon('SG-20 Halt')", w.LuaPreview); }
    }

    // ---- SDK 0.28.1 (ModBuilder 1.4.2) -------------------------------------------------------------------------------------------------
    // 0.28.0 added allow_unverified_effect to 146 fields 0.27.0 wrote without it (the PLAS-101 Purifier's among them). Runtime 0.28.1 applies an
    // SDK 0.27-era operation that lacks it, deciding by the SDK version the export's wrapper declares (local x,y,z=version('<sdk>')); SDK
    // 0.28.0+ declarations get the current rule. So ModBuilder declares each project's bound SDK, emits exactly what that SDK requires, and
    // never rebinds a project on its own.
    private const string Purifier = "PLAS-101 Purifier", PurifierDamage = "explosion.primary.impact.damage.standard_damage";
    private static int Count(string text, string value) => (text.Length - text.Replace(value, "", StringComparison.Ordinal).Length) / value.Length;
    private static BuilderWorkspace Upgraded(TestEnvironment e)
    {
        var cache = new SdkCache(e.Paths, e.Reader, e.GitHub); e.GitHub.Offline = true;
        return new BuilderWorkspace(e.Store, e.Projects, cache, new SdkUpdateService(cache, e.GitHub, e.Paths), e.Changes, e.Generator, e.Exporter, e.Desktop, e.Desktop, e.Paths);
    }
    // What the export declares: the manifest's minimum Runtime and SDK, and the SDK version the wrapper hands Runtime.
    private static async Task<(string MinVersion, string Addon, string Wrapper)> Export(BuilderWorkspace w)
    {
        await w.ExportAsync();
        using var zip = System.IO.Compression.ZipFile.OpenRead(w.LastExport!);
        string Entry(string name) { using var r = new StreamReader(zip.GetEntry(name)!.Open()); return r.ReadToEnd(); }
        var manifest = System.Text.Json.Nodes.JsonNode.Parse(Entry("hd2runtime.json"))!;
        var min = (string)manifest["requires"]!["hd2runtime"]!["min_version"]!;
        return (min, Entry("src/addon.lua"), Core.Generation.ModExporter.WrapFor(w.Project!, w.LuaPreview, min));
    }

    [Fact] public async Task A_project_on_SDK_0_28_1_carries_the_opt_in_0_28_requires_and_keeps_the_plain_wrapper()
    {
        // ModBuilder 1.4.2 made new projects on SDK 0.28.1; they keep it (and its exact wrapper) until they are rebound.
        using var e = new TestEnvironment(); var sdk = await SdkFixtures.Install(e, "0.28.1"); var w = e.Workspace();
        await w.CreateAsync(new("Purifier 0.28.1", "Tests", "mods/tests/purifier_0281", "0.1.0"), sdk);
        Assert.Equal("0.28.1", w.Project!.SdkVersion);
        await w.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        Assert.Null(w.BuildError); Assert.Equal(1, Count(w.LuaPreview, "allow_unverified_effect=true"));
        var (min, addon, wrapper) = await Export(w);
        Assert.Equal("0.28.1", min); Assert.Equal(w.LuaPreview, addon); Assert.Contains("local x,y,z=version('0.28.1')", wrapper);
        Assert.Equal(Core.Generation.ModExporter.Wrap(w.Project!, w.LuaPreview), wrapper); Assert.DoesNotContain("required_runtime", wrapper);
    }

    // ---- SDK 0.30.0 (ModBuilder 1.7.0), 0.30.2 (the 1.7.x SDK move), 0.30.3 (1.7.1) and 0.31.0 (1.8.0) ------------------------------------
    // The bundled SDK is HD2Runtime 0.31.0. New projects bind it; from 0.30 on their wrapper checks the installed Runtime by SemVer (the plain
    // wrapper's pattern refuses the '0.30.0-dev' of the test SDKs) and still declares the bound SDK as local x,y,z, which Runtime's
    // core/sdk_compatibility.lua reads (only the MAJOR.MINOR.PATCH core).
    [Fact] public async Task A_new_project_binds_the_pinned_SDK_with_the_SemVer_wrapper()
    {
        using var e = new TestEnvironment(); var w = Upgraded(e); await w.InitializeAsync();
        Assert.Equal("0.31.0", SdkPin.Version); Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version); Assert.True(w.SdkStatus.Installed.IsPinnedBuild);
        await w.CreateAsync(new("Purifier 0.30", "Tests", "mods/tests/purifier_030", "0.1.0"), w.SdkStatus.Installed);
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion);
        await w.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        Assert.Null(w.BuildError); Assert.Equal(1, Count(w.LuaPreview, "allow_unverified_effect=true"));
        var (min, addon, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Equal(w.LuaPreview, addon);
        Assert.Contains("local x,y,z=version('0.31.0')", wrapper); Assert.Contains("local required_runtime='0.31.0'", wrapper);
        Assert.Contains("local function at_least(have,need)", wrapper); Assert.Contains("local key='HD2RuntimeMod:mods/tests/purifier_030'", wrapper);
        Assert.Equal(Core.Generation.ModExporter.Wrap(w.Project!, w.LuaPreview, SdkPin.Version), wrapper);
    }

    // 0.30.0 adds allow_unverified_effect to the 30 PLAS-45 Epoch primary / primary_impact fields (their row is now known to be fired only by the
    // partial-charge shot). Runtime applies a 0.28.x export's write without it as a legacy operation; rebinding moves the edit to the pinned
    // 0.30.3 unchanged, the generated operation carries the opt-in (never a manual acknowledgement), and the export declares the pin.
    private const string Epoch = "PLAS-45 Epoch", EpochVelocity = "support-field/v1/plas-45-epoch/projectile-reference/primary/projectile-velocity/9ed92fa3a82b5806";
    [Fact] public async Task An_SDK_0_28_1_Epoch_edit_rebinds_to_0_30_with_the_opt_in_0_30_requires()
    {
        using var e = new TestEnvironment(); var old = await SdkFixtures.Install(e, "0.28.1"); var w0 = e.Workspace();
        await w0.CreateAsync(new("Epoch 0.28.1", "Tests", "mods/tests/epoch_0281", "0.1.0"), old);
        Assert.Null(old.SupportAuthoring!.Field(EpochVelocity).Operation.Acknowledgement);
        await w0.SetSupportAsync(EpochVelocity, "300");
        var id = w0.Project!.Id; var lua0281 = w0.LuaPreview; var saved = File.ReadAllBytes(e.Paths.ProjectFile(id));
        Assert.Null(w0.BuildError); Assert.DoesNotContain("allow_unverified_effect", Operation(lua0281, Epoch));
        // The 1.7.0 ModBuilder opens it: binding, file and operations are untouched, and the export still declares 0.28.1 with the plain wrapper.
        var w = Upgraded(e); await w.InitializeAsync(); await w.OpenAsync(id);
        Assert.Equal("0.28.1", w.Project!.SdkVersion); Assert.Equal(saved, File.ReadAllBytes(e.Paths.ProjectFile(id))); Assert.Equal(lua0281, w.LuaPreview);
        var (min, _, wrapper) = await Export(w);
        Assert.Equal("0.28.1", min); Assert.Equal(Core.Generation.ModExporter.Wrap(w.Project!, w.LuaPreview), wrapper);
        // Rebinding keeps the edit and its baseline, and the operation now carries 0.30's opt-in.
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion); Assert.Null(w.BuildError);
        var change = Assert.Single(w.Project.SupportChanges);
        Assert.Equal((EpochVelocity, "300", "250"), (change.InstanceKey, change.DesiredValue.GetRawText(), change.ExpectedValue.GetRawText()));
        Assert.Equal("allow_unverified_effect", w.Metadata!.SupportAuthoring!.Field(EpochVelocity).Operation.Acknowledgement);
        Assert.Contains("allow_unverified_effect=true", Operation(w.LuaPreview, Epoch));
        (min, _, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Contains("local x,y,z=version('" + SdkPin.Version + "')", wrapper);
        Assert.Equal(SdkPin.Version, (await e.Store.LoadAsync(id)).SdkVersion);
    }
    // A tester's project bound to the 0.30.0-dev test SDK (an earlier 1.7.0 build bundled it): the upgraded ModBuilder makes the bundled 0.30.3
    // current, opens the project untouched on its cached 0.30.0-dev, exports it as before (HD2Runtime 0.30.x loads mods that declare
    // 0.30.0-dev), and rebinding to 0.30.3 keeps every edit and operation and declares 0.30.3.
    [Fact] public async Task A_project_bound_to_the_0_30_0_dev_test_SDK_opens_exports_and_rebinds_to_the_pin()
    {
        using var e = new TestEnvironment(); var dev = await SdkFixtures.Install(e, "0.30.0-dev"); var w0 = e.Workspace();
        Assert.Equal("0.30.0-dev", dev.Version); Assert.Null(dev.IsPinnedBuild);
        await w0.CreateAsync(new("Purifier 0.30.0-dev", "Tests", "mods/tests/purifier_030dev", "0.1.0"), dev);
        await w0.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        var id = w0.Project!.Id; var luaDev = w0.LuaPreview; var saved = File.ReadAllBytes(e.Paths.ProjectFile(id));
        Assert.Null(w0.BuildError); Assert.Equal(1, Count(luaDev, "allow_unverified_effect=true"));
        var w = Upgraded(e); await w.InitializeAsync();
        Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version); Assert.True(w.SdkStatus.Installed.IsPinnedBuild);
        await w.OpenAsync(id);
        Assert.Equal("0.30.0-dev", w.Project!.SdkVersion); Assert.Equal(saved, File.ReadAllBytes(e.Paths.ProjectFile(id))); Assert.Equal(luaDev, w.LuaPreview);
        var (min, _, wrapper) = await Export(w);
        Assert.Equal("0.30.0-dev", min); Assert.Contains("local x,y,z=version('0.30.0-dev')", wrapper); Assert.Contains("local required_runtime='0.30.0-dev'", wrapper);
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion); Assert.Null(w.BuildError); Assert.Equal(luaDev, w.LuaPreview);
        (min, _, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Contains("local x,y,z=version('" + SdkPin.Version + "')", wrapper);
        Assert.Equal(SdkPin.Version, (await e.Store.LoadAsync(id)).SdkVersion);
    }
    // A ModBuilder 1.7.0 project, bound to the HD2Runtime 0.30.0 release 1.7.0 bundled (cached by 1.7.0): the upgraded ModBuilder makes the
    // bundled 0.30.3 current, opens the project untouched on its 0.30.0, exports it declaring 0.30.0, and rebinding to 0.30.3 keeps every edit and
    // operation and declares 0.30.3. What 0.30.2 renamed or retired is reported where it is used, with the fix there: a custom stratagem's old
    // sound name offers its new name in place, and a swap to the retired SMG-37 Defender (projectile 150) says so at its selector until another
    // projectile (or the attack's own) is chosen.
    private const string Retired = "output/v1/projectile/smg-37-defender-projectile-150", Reprimand = "SMG-32 Reprimand";
    [Fact] public async Task A_project_bound_to_the_0_30_0_release_opens_exports_and_rebinds_to_the_pin()
    {
        using var e = new TestEnvironment(); var release = await SdkFixtures.Install(e, Runtime030Tests.Release); var w0 = e.Workspace();
        Assert.Equal(Runtime030Tests.Release, release.Version); Assert.False(release.IsPinnedBuild ?? false);
        await w0.CreateAsync(new("Purifier 0.30.0", "Tests", "mods/tests/purifier_0300", "0.1.0"), release);
        await w0.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        var id = w0.Project!.Id; var lua030 = w0.LuaPreview; var saved = File.ReadAllBytes(e.Paths.ProjectFile(id));
        Assert.Null(w0.BuildError);
        var w = Upgraded(e); await w.InitializeAsync();
        Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version); Assert.True(w.SdkStatus.Installed.IsPinnedBuild);
        await w.OpenAsync(id);
        Assert.Equal(Runtime030Tests.Release, w.Project!.SdkVersion); Assert.Equal(saved, File.ReadAllBytes(e.Paths.ProjectFile(id))); Assert.Equal(lua030, w.LuaPreview);
        var (min, _, wrapper) = await Export(w);
        Assert.Equal(Runtime030Tests.Release, min); Assert.Contains("local x,y,z=version('0.30.0')", wrapper); Assert.Contains("local required_runtime='0.30.0'", wrapper);
        // What 1.7.0 could save on 0.30.0 and 0.30.2 renamed or retired: a swap to SMG-37 Defender (projectile 150), and a custom Pelican whose
        // gun plays a sound name 0.30.2 renamed.
        Assert.Contains(w.Metadata!.AttackOutputs!.Outputs, o => o.SemanticId == Retired);
        await w.SetAttackOutputAsync(Reprimand, "primary", Retired);
        var gunship = await w.CreateCustomStratagemFromTemplateAsync("SimplePelican");
        await w.EditCustomStratagemAsync(gunship, s => (s.Delivery.Pelican!.Gun ??= new()).Sound = "primary/smg37/seaf");
        // The renamed sound: the schema's refusal under the field, and the new name offered there; choosing it clears the problem.
        var owner = Core.CustomContent.CustomDiagnostic.StratagemOwner(gunship);
        Assert.Contains(w.CustomDiagnosticsFor(owner), d => d.Severity == Core.CustomContent.CustomSeverity.Error && d.About("payload.gun.sound"));
        var renamed = w.CustomTarget.RenamedChoice("payload.gun.sound", "primary/smg37/seaf");
        Assert.Equal("seaf/3", renamed);
        await w.EditCustomStratagemAsync(gunship, s => s.Delivery.Pelican!.Gun!.Sound = renamed);
        Assert.DoesNotContain(w.CustomDiagnosticsFor(owner), d => d.About("payload.gun.sound") && d.Severity == Core.CustomContent.CustomSeverity.Error);
        // On its 0.30.0 binding the export still declares that SDK, and requires 0.30.2 for the sound name 0.30.0 does not know.
        Assert.Null(w.BuildError);
        (min, _, wrapper) = await Export(w);
        Assert.Equal("0.30.2", min); Assert.Contains("local x,y,z=version('0.30.0')", wrapper);
        // Rebinding to 0.30.3 keeps the edits; the retired donor is reported at its selector (never a crash), and restoring the attack's own
        // projectile resolves it.
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion); Assert.Single(w.Project.CompositionChanges);
        var swap = Assert.Single(w.Project.AttackOutputChanges!);
        Assert.NotNull(w.AttackOutputIssue(swap));
        await w.SetAttackOutputAsync(Reprimand, "primary", null);
        Assert.Null(w.Project.AttackOutputChanges); Assert.Null(w.BuildError);
        (min, _, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Contains("local x,y,z=version('" + SdkPin.Version + "')", wrapper);
    }
    // A project bound to 0.30.2 (the SDK of the 1.7.x SDK move, before 1.7.1 pinned 0.30.3): the upgraded ModBuilder makes the bundled pin
    // current, opens the project untouched on its 0.30.2 (fixture sdk-0.30.2.zip), exports it declaring 0.30.2, and rebinding to the pin keeps
    // every edit and operation and declares the pin.
    [Fact] public async Task A_project_bound_to_0_30_2_opens_exports_and_rebinds_to_the_pin()
    {
        using var e = new TestEnvironment(); var v0302 = await SdkFixtures.Install(e, Runtime030Tests.Previous); var w0 = e.Workspace();
        Assert.Equal("0.30.2", v0302.Version); Assert.False(v0302.IsPinnedBuild ?? false);
        await w0.CreateAsync(new("Purifier 0.30.2", "Tests", "mods/tests/purifier_0302", "0.1.0"), v0302);
        await w0.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        var id = w0.Project!.Id; var lua0302 = w0.LuaPreview; var saved = File.ReadAllBytes(e.Paths.ProjectFile(id));
        Assert.Null(w0.BuildError); Assert.Equal(1, Count(lua0302, "allow_unverified_effect=true"));
        var w = Upgraded(e); await w.InitializeAsync();
        Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version); Assert.True(w.SdkStatus.Installed.IsPinnedBuild);
        await w.OpenAsync(id);
        Assert.Equal("0.30.2", w.Project!.SdkVersion); Assert.Equal(saved, File.ReadAllBytes(e.Paths.ProjectFile(id))); Assert.Equal(lua0302, w.LuaPreview);
        var (min, _, wrapper) = await Export(w);
        Assert.Equal("0.30.2", min); Assert.Contains("local x,y,z=version('0.30.2')", wrapper); Assert.Contains("local required_runtime='0.30.2'", wrapper);
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion); Assert.Null(w.BuildError); Assert.Equal(lua0302, w.LuaPreview);
        (min, _, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Contains("local x,y,z=version('" + SdkPin.Version + "')", wrapper);
        Assert.Equal(SdkPin.Version, (await e.Store.LoadAsync(id)).SdkVersion);
    }
    // The generated operation (pcall-isolated block) that names a weapon.
    private static string Operation(string lua, string weapon) => System.Text.RegularExpressions.Regex.Split(lua, @"(?=add\(function\(\) return )")
        .Single(b => b.Contains("'" + weapon + "'", StringComparison.Ordinal));

    [Fact] public async Task An_SDK_0_27_project_keeps_its_binding_until_it_is_rebound_to_0_28_1()
    {
        using var e = new TestEnvironment();
        // Made with an SDK 0.27.0 ModBuilder: the Purifier edit carries no opt-in (0.27.0 required none).
        var old = await SdkFixtures.Install(e, "0.27.0"); var w0 = e.Workspace();
        await w0.CreateAsync(new("Purifier 0.27.0", "Tests", "mods/tests/purifier_0270", "0.1.0"), old);
        await w0.SetObjectScalarAsync(Purifier, "primary", "explosion", "impact", PurifierDamage, "900", true);
        var id = w0.Project!.Id; var saved = File.ReadAllBytes(e.Paths.ProjectFile(id)); var lua027 = w0.LuaPreview;
        Assert.DoesNotContain("allow_unverified_effect", lua027);
        // A later ModBuilder (the bundled SDK current) opens the project: the binding and the saved file are untouched.
        var w = Upgraded(e); await w.InitializeAsync(); Assert.Equal(SdkPin.Version, w.SdkStatus!.Installed.Version);
        await w.OpenAsync(id);
        Assert.Equal("0.27.0", w.Project!.SdkVersion); Assert.Equal(saved, File.ReadAllBytes(e.Paths.ProjectFile(id)));
        // It still generates SDK 0.27.0's operations and declares SDK 0.27.0: whether Runtime 0.28.1 applies them as legacy operations is
        // Runtime's decision, not duplicated here (no opt-in is added for a project that did not ask for one).
        Assert.Null(w.BuildError); Assert.Equal(lua027, w.LuaPreview);
        var (min, _, wrapper) = await Export(w);
        Assert.Equal("0.27.0", min); Assert.Contains("local x,y,z=version('0.27.0')", wrapper);
        Assert.Equal("0.27.0", (await e.Store.LoadAsync(id)).SdkVersion);
        // Rebinding is the explicit step: the edit is kept, generated with the pinned SDK's opt-in, and the export declares that SDK.
        await w.RebindToInstalledSdkAsync();
        Assert.Equal(SdkPin.Version, w.Project!.SdkVersion); Assert.Single(w.Project.CompositionChanges); Assert.Null(w.BuildError);
        Assert.Equal(1, Count(w.LuaPreview, "allow_unverified_effect=true"));
        (min, _, wrapper) = await Export(w);
        Assert.Equal(SdkPin.Version, min); Assert.Contains("local x,y,z=version('" + SdkPin.Version + "')", wrapper);
        Assert.Equal(SdkPin.Version, (await e.Store.LoadAsync(id)).SdkVersion);
    }

    [Fact] public async Task An_SDK_0_28_0_project_stays_on_0_28_0_and_rebinding_to_0_28_1_keeps_every_operation()
    {
        // Saved by the 1.4.0 release candidate on SDK 0.28.0. 0.28.1 publishes the same capabilities, so its operations are identical; only
        // the declared SDK moves, and only on rebind (here to an installed 0.28.1; the bundled SDK is 0.30.0).
        using var e = new TestEnvironment(); await SdkFixtures.Install(e, "0.28.0"); await SdkFixtures.Install(e, "0.28.1");
        var project = await e.Store.ImportAsync(Path.Combine(AppContext.BaseDirectory, "Fixtures", "projects-1.4.0-rc", "runtime028-smoke.hd2mod.json"));
        var w = e.Workspace(); e.GitHub.Offline = true; await w.InitializeAsync(); await w.OpenAsync(project.Id);
        Assert.Equal("0.28.0", w.Project!.SdkVersion); Assert.Null(w.BuildError);
        var lua = w.LuaPreview; var (min, _, _) = await Export(w); Assert.Equal("0.28.0", min);
        await w.RebindToInstalledSdkAsync();
        Assert.Equal("0.28.1", w.Project!.SdkVersion); Assert.Null(w.BuildError); Assert.Equal(lua, w.LuaPreview);
        (min, _, _) = await Export(w); Assert.Equal("0.28.1", min);
    }

    // ---- Projects saved by ModBuilder 1.4.2 itself (ModBuilder 1.5.0, project format 12) -----------------------------------------------
    // Fixtures/projects-1.4.2: the 13 projects the packaged 1.4.2 release candidate (32df794) saved in its own smoke runs, byte for byte
    // (formats 4, 5, 6, 9 and 11; SDK 0.27.0 and 0.28.1; weapons, a projectile swap, support weapons, stratagems, a vehicle and backpack,
    // a booster and throwable, programmable ammo, projectile-builder rows, attack outputs and custom Lua), each with the ZIP the 1.4.2 app
    // exported from it (*.v142.zip). 1.5.0 adds additional packaged files in format 12: none of these may be rewritten by opening, gain a
    // packagedFiles section, or change format or SDK when saved, and each exports what 1.4.2 exported, apart from the builder version in
    // build-report.json.
    private static string Folder142 => Path.Combine(AppContext.BaseDirectory, "Fixtures", "projects-1.4.2");
    public static IEnumerable<object[]> Projects142() => Directory.GetFiles(Folder142, "*.hd2mod.json").Select(f => new object[] { Path.GetFileName(f)[..^".hd2mod.json".Length] });
    private static byte[] Read(System.IO.Compression.ZipArchiveEntry entry) { using var s = entry.Open(); using var m = new MemoryStream(); s.CopyTo(m); return m.ToArray(); }

    [Theory] [MemberData(nameof(Projects142))]
    public async Task A_1_4_2_project_opens_saves_and_exports_as_1_4_2_did(string name)
    {
        using var e = new TestEnvironment(); await SdkFixtures.Install(e, "0.27.0"); await SdkFixtures.Install(e, "0.28.1");
        var path = Path.Combine(Folder142, name + ".hd2mod.json");
        var original = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!.AsObject();
        var id = (await e.Store.ImportAsync(path)).Id; var file = e.Paths.ProjectFile(id); var stored = File.ReadAllBytes(file);
        var w = e.Workspace(); await w.OpenAsync(id);
        // Opening rewrites nothing and adds nothing; the SDK binding and format stay as 1.4.2 saved them.
        Assert.Equal(stored, File.ReadAllBytes(file)); Assert.Null(w.Project!.PackagedFiles);
        Assert.Equal((string)original["sdkVersion"]!, w.Project.SdkVersion); Assert.Equal((int)original["formatVersion"]!, w.Project.FormatVersion);
        // A plain save keeps every saved value except the save time (and the export directory it saves).
        await w.SaveExportDirectoryAsync(e.Paths.Exports);
        var saved = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(file))!.AsObject();
        Assert.False(saved.ContainsKey("packagedFiles"));
        foreach (var key in new[] { "modifiedAt", "exportDirectory" }) { original.Remove(key); saved.Remove(key); }
        Assert.True(System.Text.Json.Nodes.JsonNode.DeepEquals(original, saved), "saved project differs from 1.4.2's");
        // The export is 1.4.2's ZIP entry for entry (names, order, timestamps, attributes, bytes); build-report.json names the builder.
        await w.ExportAsync();
        using var now = System.IO.Compression.ZipFile.OpenRead(w.LastExport!);
        using var v142 = System.IO.Compression.ZipFile.OpenRead(Path.Combine(Folder142, name + ".v142.zip"));
        Assert.Equal(v142.Entries.Select(x => x.FullName), now.Entries.Select(x => x.FullName));
        foreach (var before in v142.Entries)
        {
            var after = now.GetEntry(before.FullName)!;
            Assert.Equal(before.LastWriteTime, after.LastWriteTime); Assert.Equal(before.ExternalAttributes, after.ExternalAttributes);
            if (before.FullName != "build-report.json") { Assert.Equal(Read(before), Read(after)); continue; }
            var (a, b) = (System.Text.Json.Nodes.JsonNode.Parse(Read(before))!.AsObject(), System.Text.Json.Nodes.JsonNode.Parse(Read(after))!.AsObject());
            Assert.Equal("HD2Runtime ModBuilder 1.4.2 / .NET 10", (string)a["builder"]!); Assert.Equal($"{Core.BuildInfo.ProductName} {Core.BuildInfo.Version} / .NET 10", (string)b["builder"]!);
            a.Remove("builder"); b.Remove("builder"); Assert.True(System.Text.Json.Nodes.JsonNode.DeepEquals(a, b), "build-report.json differs beyond the builder");
        }
    }
}
